
-- 2025-09-11 Mass approving Yellow tags

DECLARE @t TABLE ([ID] INT IDENTITY(0,1), [WO] INT)
;

SELECT COUNT(*) AS [NFromLori] FROM @t;
SELECT COUNT(*) AS [NUniqueFromLori] FROM (SELECT [WO] FROM @t GROUP BY [WO]) AS [Src];

BEGIN TRAN;

UPDATE
	[BWSdb].[dbo].[PROD_YellowTags]
SET
	[Active] = 0
FROM
	[BWSdb].[dbo].[PROD_YellowTags] [YT]
INNER JOIN
	@t [T]
ON
	[YT].[WO] = [T].[WO]

ROLLBACK;
COMMIT;